"""Regenerate docs/STYLES.md: one sample citation + bibliography per style."""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from wordcite import CitationEngine, CiteItem, Cluster, list_styles, load_references

ROOT = Path(__file__).resolve().parents[1]
KEYS = ["smith2020", "kahneman2011", "brown2019", "who2023", "rezaei1399"]


def main():
    lib = load_references(ROOT / "examples" / "references.bib")
    lib = {k: lib[k] for k in KEYS}
    out = ["# Style gallery", "",
           "Generated by `python scripts/gen_style_docs.py` from `examples/references.bib`.", ""]
    out += ["| id | name | type | used in |", "|---|---|---|---|"]
    out += [f"| `{s.id}` | {s.name} | {s.kind} | {s.discipline} |" for s in list_styles()]
    for s in list_styles():
        e = CitationEngine(lib, s)
        clusters = [Cluster([CiteItem("smith2020", locator="p. 125")]), Cluster([CiteItem("kahneman2011")], True),
                    Cluster([CiteItem("brown2019"), CiteItem("who2023")]), Cluster([CiteItem("rezaei1399")])]
        for c in clusters:
            e.register(c)
        e.finalize()
        cites = [e.format_cluster(c).to_markdown() for c in clusters]
        out += ["", f"## {s.name} (`{s.id}`)", "",
                f"In text: {cites[0]} · narrative: {cites[1]} · multiple: {cites[2]} · Persian: {cites[3]}", ""]
        for b in e.bibliography():
            out.append(f"- {(b.label + ' ') if b.label else ''}{b.text.to_markdown()}")
    (ROOT / "docs" / "STYLES.md").write_text("\n".join(out) + "\n", encoding="utf-8")
    print("wrote docs/STYLES.md")


if __name__ == "__main__":
    main()
